/* SmartTutors72 browser application. No dependencies or build step. */
'use strict';
const $ = (selector,root=document) => root.querySelector(selector);
const $$ = (selector,root=document) => [...root.querySelectorAll(selector)];
const esc = value => String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = cents => cents===null||cents===undefined ? 'Custom quote' : new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:cents%100?2:0}).format(cents/100);
const zone = Intl.DateTimeFormat().resolvedOptions().timeZone || 'UTC';
const date = value => value ? new Intl.DateTimeFormat('en-US',{dateStyle:'medium',timeStyle:'short',timeZone:zone}).format(new Date(value)) : 'To be agreed';
const shortDate = value => value?new Intl.DateTimeFormat('en-US',{dateStyle:'medium',timeZone:zone}).format(new Date(value)):'Flexible';
const labels={awaiting_quote:'Awaiting quote',awaiting_payment:'Awaiting payment',received:'Received',in_progress:'In progress',ready_for_review:'Ready for review',revision_requested:'Revision requested',completed:'Completed',cancelled:'Cancelled',unpaid:'Unpaid',paid:'Paid'};
const status = value => `<span class="status ${esc(value)}">${esc(labels[value]||value)}</span>`;
const paths={pen:'m4 20 4-1 12-12-5-5L3 14l1 6Zm8-15 5 5M3 21h18',book:'M12 6c-3-3-7-3-10-2v15c4-1 7-1 10 2 3-3 6-3 10-2V4c-3-1-7-1-10 2Zm0 0v15',content:'M5 3h11l4 4v14H5V3Zm10 0v5h5M8 12h9M8 16h7',briefcase:'M3 7h18v14H3V7Zm5 0V3h8v4M3 12c6 4 12 4 18 0M10 13h4v3h-4v-3',user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0ZM3 21c0-7 18-7 18 0',chat:'M3 3h18v13H9l-6 5V3Zm4 5h10M7 12h6',globe:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM3 12h18M12 3c-5 5-5 13 0 18 5-5 5-13 0-18Z',check:'m5 12 4 4L19 6',shield:'m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6l9-4Zm-5 10 3 3 7-7',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM12 7v6l4 2',upload:'M12 16V3m-5 5 5-5 5 5M3 15v6h18v-6',spark:'m12 1 2.8 8.2L23 12l-8.2 2.8L12 23l-2.8-8.2L1 12l8.2-2.8L12 1Z'};
const icon = name => `<svg viewBox="0 0 24 24" width="24" height="24" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.pen}"/></svg>`;
const serviceIcons={editing:'pen',academic:'book',content:'content',business:'briefcase',career:'user',coaching:'chat'};
const serviceDetails={
  editing:{intro:'Let your ideas take the lead. We help you refine grammar, structure, readability, and tone while keeping your voice intact.',audience:'Students, authors, professionals, and anyone with a draft to refine.',deliverables:'An edited document and project-specific feedback agreed in your quote.',need:'Your draft, intended audience, preferred English variant, and deadline.',scope:'Proofreading, line editing, structural feedback, and consistency checks.'},
  academic:{intro:'Make progress with thoughtful feedback on your own academic work. Get support with clarity, research organization, and citation formatting.',audience:'Students and researchers seeking guidance and editing support.',deliverables:'Editorial feedback, citation corrections, or research guidance as agreed.',need:'Your draft, assignment guidance, citation style, academic level, and questions.',scope:'Academic editing, literature-search guidance, referencing, and research organization.'},
  content:{intro:'Turn your message into writing your audience wants to read. Bring us your purpose, voice, and brief; we will help shape the words.',audience:'Businesses, creators, and professionals developing their online presence.',deliverables:'Original copy based on your brief, with the agreed length and format.',need:'Your audience, brand voice, topic, key facts, and examples you like.',scope:'Website copy, articles, blog posts, and brand content.'},
  business:{intro:'Make complex ideas easier to act on. Get support with professional documents and presentations tailored to your audience.',audience:'Business owners, teams, and professionals.',deliverables:'A project-specific document or presentation in the agreed format.',need:'Your purpose, audience, source information, preferred format, and deadline.',scope:'Proposals, reports, presentations, professional profiles, and business communications.'},
  career:{intro:'Give your experience a clear story. We help organize your achievements and tailor your application documents to your next opportunity.',audience:'Job seekers and professionals updating their career documents.',deliverables:'A tailored CV, résumé, or cover letter based on the selected scope.',need:'Your current document, work history, achievements, and target role.',scope:'Document editing, structure, achievement statements, and role-specific tailoring.'},
  coaching:{intro:'Build confidence one conversation at a time. Work through writing questions, develop your approach, and learn practical strategies.',audience:'Learners who want to strengthen their own writing skills.',deliverables:'A coaching session and agreed guidance for your next steps.',need:'Your learning goals, questions, availability, and any relevant work.',scope:'Writing planning, feedback discussions, research skills, and revision strategies.'}
};
let config=null, session={user:null,csrf:''}, currentOrder=null, adminData=null, adminTab='orders', orderStep=0, uploads=[];
let draft={service:'editing',quantity:1,title:'',subject:'',instructions:'',deadlineLocal:'',language:'US English',level:'',citation:''};
try {draft={...draft,...JSON.parse(sessionStorage.getItem('st72-draft')||'{}')};}catch{}
