let renderId=0, toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),5000);}
async function api(url,options={}) {
  const headers={'X-CSRF-Token':session.csrf,...options.headers};
  if(options.body && !(options.body instanceof File) && !(options.body instanceof Blob)){headers['Content-Type']='application/json';options.body=JSON.stringify(options.body);}
  const response=await fetch(url,{...options,headers,credentials:'same-origin'});
  const payload=await response.json();
  if(!response.ok) {const error=new Error(payload.error||'Unable to complete this request.');error.status=response.status;throw error;}
  return payload;
}
function setMain(html){$('#main').innerHTML=html;}
function heading(kicker,title,description=''){return `<div class="container page-hero reveal"><div class="eyebrow">${kicker}</div><h1>${title}</h1>${description?`<p>${description}</p>`:''}</div>`;}
function cta(){return `<div class="container"><section class="cta"><div><h2>Your next chapter starts here.</h2><p>A fresh idea, a working draft, or a project that needs a little direction.</p></div><a class="button" href="/order" data-link>Let’s get started <span aria-hidden="true">→</span></a></section></div>`;}
function serviceCards(){return config.services.map(s=>`<a href="/services/${s.id}" data-link class="service-card"><span class="icon-wrap">${icon(serviceIcons[s.id])}</span><h3>${esc(s.name)}</h3><p>${esc(s.description)}</p><span class="service-bottom"><span>${s.rate===null?'Quoted for your project':`From ${money(s.rate)} / ${esc(s.unit)}`}</span><span class="arrow" aria-hidden="true">→</span></span></a>`).join('');}
function steps(){return `<div class="steps"><div><span class="step-number">01</span><h3>Tell us what you need</h3><p>Choose your service and share your goals, draft, and deadline.</p></div><div><span class="step-number">02</span><h3>Make a clear plan</h3><p>Review your personalized quote and the scope of your project.</p></div><div><span class="step-number">03</span><h3>Stay in the loop</h3><p>Confirm payment, follow progress, and keep your messages in one place.</p></div><div><span class="step-number">04</span><h3>Move forward</h3><p>Download your files, review the work, and discuss any revisions.</p></div></div>`;}
function faqItems(){return [
  ['Do you work with customers outside the U.S.?','Yes. SmartTutors72 is based in the United States and serves customers worldwide. You can submit your project online and track it through your dashboard.'],
  ['How much does a project cost?',`Eligible services start at $10 per page. The calculator gives a starting estimate; your final quote depends on the service, scope, and deadline. You review the confirmed amount before payment.${config.wordsPerPage?` Page-based quotes use ${config.wordsPerPage} words per page.`:' The page-length definition is confirmed with your quote.'}`],
  ['What should I include in my brief?','Tell us your purpose, audience, preferred style, and deadline. Upload your draft, relevant guidance, and any supporting documents so the scope can be confirmed.'],
  ['Can I request revisions?','You can submit a revision request through your order dashboard after delivery. The project team will review it against the scope and revision terms agreed in your quote.'],
  ['How do I receive my work?','Completed files appear in your order dashboard. Your instructions, messages, and downloads stay together so you can follow the project from start to finish.'],
  ['What academic support do you offer?','We offer editing, citation formatting, research guidance, and writing coaching to support your own learning and work. Share the type of help you need when placing your request.']
].map(([q,a])=>`<details><summary>${q}</summary><p>${esc(a)}</p></details>`).join('');}
function renderHome(){setMain(`<div class="container"><section class="hero reveal"><div><div class="eyebrow">Good ideas deserve great writing</div><h1>Your ideas.<br><em>Clearly written.</em></h1><p class="intro">Personalized writing, editing, and research support for students, professionals, and businesses. Based in the U.S. Here for you, worldwide.</p><div class="actions"><a class="button" href="/order" data-link>Start your project <span aria-hidden="true">→</span></a><a class="text-link" href="/services" data-link>Explore our services <span aria-hidden="true">→</span></a></div><div class="hero-note">${icon('check')} From $10 per page · A clear quote before you pay</div></div><div><div class="hero-art"><span class="orbit-mark">${icon('spark')}</span><div class="paper"><div class="paper-label"><span>A LITTLE CLARITY GOES A LONG WAY</span><span>01 / 01</span></div><h2>Every good idea<br>deserves <span>the right words.</span></h2><p>We help you <del>make your writing better</del> <ins>find your clearest voice.</ins> One thoughtful edit. One stronger sentence. One step forward.</p><div class="paper-foot">${icon('check')} Your voice, thoughtfully refined.</div></div><div class="edit-note">That’s more like you.</div><div class="hero-estimate"><span class="label">A clearer starting point</span><div class="amount">$10<small> / page</small></div><a href="/pricing" data-link>Build your estimate →</a></div></div><p class="art-caption">An illustrative editing example. Your project, your voice.</p></div></section><div class="trust-strip"><span>${icon('globe')} Worldwide service</span><span>${icon('pen')} Personal to your project</span><span>${icon('chat')} Direct communication</span><span>${icon('shield')} Private order workspace</span></div></div><section class="container section"><div class="section-head"><div><div class="eyebrow">Find your kind of support</div><h2>Different goals.<br>The right words for each.</h2></div><p>From a first draft to a final polish, choose the support that meets you where you are.</p></div><div class="services-grid">${serviceCards()}</div></section><section class="process section"><div class="container"><div class="section-head"><div><div class="eyebrow">A little structure. A lot less stress.</div><h2>From “where do I start?”<br>to “ready to go.”</h2></div><a class="text-link" href="/how-it-works" data-link>See how it works <span aria-hidden="true">→</span></a></div>${steps()}</div></section><section class="edit-section section"><div class="container editing-layout"><div><div class="eyebrow">See what clarity can do</div><h2>The same idea.<br>A stronger impression.</h2><p>Good editing brings your meaning into focus. Explore a simple example of how a few thoughtful changes can make writing easier to read.</p></div><div class="editing-demo"><div class="switch" aria-label="Editing example"><button data-example="before" aria-pressed="false">Before</button><button data-example="after" aria-pressed="true">After editing</button></div><blockquote id="example-copy">“Our goal is simple: help you communicate your ideas clearly and confidently.”</blockquote><div class="example-caption" id="example-caption">Clear purpose. Fewer distractions. A more natural voice. · Illustrative sample.</div></div></div></section><section class="container section faq-layout"><div><div class="eyebrow">A few things you might wonder</div><h2>Good questions.<br>Clear answers.</h2><p>Need help deciding what your project needs? We’re a message away.</p><a class="text-link" href="/contact" data-link>Let’s talk <span aria-hidden="true">→</span></a></div><div class="faqs">${faqItems()}</div></section>${cta()}`);}
